'use strict';

// MODULES //

var base = require( './base.js' );


// MAIN //

/**
* Adjust the underflow and overflow thresholds if the exponent range is very large.
*
* @param {Float64Array} SMALL - array containing a single element equal to the underflow threshold
* @param {Float64Array} LARGE - array containing a single element equal to the overflow threshold
* @returns {void}
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var SMALL = new Float64Array( [ 2.2250738585072014e-308 ] );
* var LARGE = new Float64Array( [ 1.7976931348623157e+308 ] );
*
* dlabad( SMALL, LARGE );
* // SMALL => <Float64Array>[ 2.2250738585072014e-308 ]
* // LARGE => <Float64Array>[ 1.7976931348623157e+308 ]
*/
function dlabad( SMALL, LARGE ) {
	return base( SMALL, 0, LARGE, 0 );
}


// EXPORTS //

module.exports = dlabad;
